// Excel 导出 - 对象列表导出示例
// 方式 1：直接查询实体列表（如果有实体类映射）
// var data = db.selectEntities("select * from sys_user where is_del = 0", SysUser.class)

// 方式 2：使用现有的 Map 数据（模拟对象列表）
var data = db.select("select id, username, email, create_time from sys_user where is_del = 0 limit 10")

// 定义表头
var headers = {
    "id": "ID",
    "username": "用户名",
    "email": "邮箱",
    "create_time": "创建时间"
}

// 使用对象导出方法
excel.downloadEntities(data, "用户导出_" + System.currentTimeMillis(), headers)
